import{_ as e,o as d,c as a,a2 as s}from"./chunks/framework.mRCPFc5l.js";const k=JSON.parse('{"title":"渲染器 / 渲染后端","description":"","frontmatter":{},"headers":[],"relativePath":"zh/api/renderer.md","filePath":"zh/api/renderer.md","lastUpdated":1790851587000}'),i={name:"zh/api/renderer.md"};function o(n,t,l,c,r,p){return d(),a("div",null,[...t[0]||(t[0]=[s('<h1 id="渲染器-渲染后端" tabindex="-1">渲染器 / 渲染后端 <a class="header-anchor" href="#渲染器-渲染后端" aria-label="Permalink to &quot;渲染器 / 渲染后端&quot;">​</a></h1><p>渲染层运行在独立线程上，通过 SPSC 环形队列消费应用线程推入的渲染命令。桌面端为 GLFW/WGL 桥接，移动端为 tgfx。具体图形后端由 <code>--render_backend</code> 标志在运行时选择。</p><h2 id="renderlayer" tabindex="-1">RenderLayer <a class="header-anchor" href="#renderlayer" aria-label="Permalink to &quot;RenderLayer&quot;">​</a></h2><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">class</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> RenderLayer</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // 通过 Application::GetRenderLayer() 获取</span></span></code></pre></div><p>通常不要直接构造。<code>Application</code> 持有它并通过以下方式暴露：</p><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">RenderLayer</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&amp;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Application</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">GetRenderLayer</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">noexcept</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>它拥有 GL/Vulkan 上下文、命令接收端，并负责每帧呈现。</p><h2 id="glfwbridge-桌面窗口与输入" tabindex="-1">GlfwBridge（桌面窗口与输入） <a class="header-anchor" href="#glfwbridge-桌面窗口与输入" aria-label="Permalink to &quot;GlfwBridge（桌面窗口与输入）&quot;">​</a></h2><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">class</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> GlfwBridge</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> : </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">public</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> NonCopyable</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>头文件：<code>&lt;neoflux/renderers/glfw_bridge.h&gt;</code>。封装 GLFW 窗口与 OpenGL 上下文， 并把系统输入翻译成 NeoFlux 回调。</p><table tabindex="0"><thead><tr><th>方法</th><th>签名</th><th>说明</th></tr></thead><tbody><tr><td><code>Init</code></td><td><code>bool Init(int w, int h, std::string_view title)</code></td><td>创建窗口。</td></tr><tr><td><code>Shutdown</code></td><td><code>void Shutdown() noexcept</code></td><td></td></tr><tr><td><code>PollEvents</code></td><td><code>void PollEvents() const</code></td><td>非阻塞。</td></tr><tr><td><code>SwapBuffers</code></td><td><code>void SwapBuffers()</code></td><td>呈现。</td></tr><tr><td><code>ShouldClose</code></td><td><code>bool ShouldClose() const</code></td><td></td></tr><tr><td><code>GetFramebufferSize</code></td><td><code>void GetFramebufferSize(int&amp; w, int&amp; h) const</code></td><td></td></tr><tr><td><code>GetWindowSize</code></td><td><code>void GetWindowSize(int&amp; w, int&amp; h) const</code></td><td></td></tr><tr><td><code>GetNativeHandle</code></td><td><code>GLFWwindow* GetNativeHandle() const noexcept</code></td><td></td></tr><tr><td><code>GetCursorPos</code></td><td><code>Point GetCursorPos() const noexcept</code></td><td></td></tr><tr><td><code>GetGlContext</code></td><td><code>void* GetGlContext() const noexcept</code></td><td>供 tgfx 使用。</td></tr><tr><td><code>MakeContextCurrent</code></td><td><code>void MakeContextCurrent()</code></td><td></td></tr><tr><td><code>ReleaseContext</code></td><td><code>static void ReleaseContext()</code></td><td>解绑。</td></tr></tbody></table><p>输入回调设置器：<code>SetInputCallback</code>、<code>SetScrollCallback</code>、<code>SetResizeCallback</code>、 <code>SetMouseMoveCallback</code>。</p><h2 id="完整-gflag-参考" tabindex="-1">完整 gflag 参考 <a class="header-anchor" href="#完整-gflag-参考" aria-label="Permalink to &quot;完整 gflag 参考&quot;">​</a></h2><p>所有标志从传给 <code>Application::Init</code> 的 <code>argc/argv</code> 解析。</p><table tabindex="0"><thead><tr><th>标志</th><th>类型</th><th>默认值</th><th>含义</th></tr></thead><tbody><tr><td><code>--render_backend</code></td><td><code>string</code></td><td><code>&quot;vulkan&quot;</code></td><td>图形后端：<code>vulkan</code>、<code>gl</code> 或 <code>cpu</code>。不可用时 <code>vulkan</code> 与 <code>cpu</code> 回退到 <code>gl</code> 并给出警告。</td></tr><tr><td><code>--target_fps</code></td><td><code>int32</code></td><td><code>60</code></td><td>事件循环帧率上限。</td></tr><tr><td><code>--render_queue_capacity</code></td><td><code>uint64</code></td><td><code>2048</code></td><td>SPSC 环形队列槽数，向上取整为 2 的幂；可用槽位 = 容量 - 1。</td></tr><tr><td><code>--verbose_logging</code></td><td><code>bool</code></td><td><code>false</code></td><td>启用详细（调试）日志。</td></tr><tr><td><code>--logtostderr</code></td><td><code>bool</code></td><td><code>false</code></td><td>glog 输出到 stderr 而非文件。</td></tr><tr><td><code>--log_dir</code></td><td><code>string</code></td><td><code>&quot;./logs&quot;</code></td><td>glog 日志目录。</td></tr></tbody></table><h3 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h3><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.\\</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">my_app.exe</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> --</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">render_backend</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">gl </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">target_fps</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">30</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> --</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">verbose_logging </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">logtostderr</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./my_app</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --render_backend=vulkan</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --render_queue_capacity=4096</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --log_dir=./logs</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">后端回退</p><p>若所选 <code>--render_backend</code> 无法创建（无 Vulkan 设备等），NeoFlux 会记录警告并回退到 OpenGL，而不是直接退出。</p></div>',19)])])}const g=e(i,[["render",o]]);export{k as __pageData,g as default};
